    ok(all(t>500 and n==0 for _,t,n,_ in out), 'ninguna cara encimada (parpadeo) en meseta y pirámide %s'%[(a,b,c) for a,b,c,_ in out]+('' if all(n==0 for _,_,n,_ in out) else ' '+str([d for *_,d in out])))
